from docx import Document
from docx.oxml.ns import qn

doc = Document('/root/offer_letter_template.docx')

# Get all text content from document body including nested tables
def iter_block_items(parent):
    """Iterate through all block items in a document or table cell."""
    from docx.table import Table
    from docx.text.paragraph import Paragraph

    parent_elm = parent.element.body if hasattr(parent, 'element') and hasattr(parent.element, 'body') else parent._element

    for child in parent_elm.iterchildren():
        if child.tag == qn('w:p'):
            yield Paragraph(child, parent)
        elif child.tag == qn('w:tbl'):
            yield Table(child, parent)

# Print all content in order
for block in iter_block_items(doc):
    if hasattr(block, 'text'):
        print(f"PARA: {block.text}")
    else:
        # It's a table
        print("TABLE:")
        for row in block.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    print(f"  CELL-PARA: {para.text}")
