from docx import Document

doc = Document('/root/offer_letter_template.docx')

# Check table cells for nested tables
for t_idx, table in enumerate(doc.tables):
    print(f"Table {t_idx}:")
    for r_idx, row in enumerate(table.rows):
        for c_idx, cell in enumerate(row.cells):
            print(f"  Row {r_idx}, Cell {c_idx}:")
            for p_idx, para in enumerate(cell.paragraphs):
                print(f"    Para {p_idx}: '{para.text}'")
            # Check for nested tables
            for nested_t in cell.tables:
                print(f"    Nested table with {len(nested_t.rows)} rows:")
                for nr_idx, nrow in enumerate(nested_t.rows):
                    for nc_idx, ncell in enumerate(nrow.cells):
                        print(f"      Nested Row {nr_idx}, Cell {nc_idx}: '{ncell.text}'")
